  ]$seed$;
  legacy_matches integer;
begin
  update private.question_pool p
  set location_lat = s.location_lat,
      location_lng = s.location_lng,
      outside_coverage = s.outside_coverage,
      status = case when s.status = 'hidden' then 'hidden' else p.status end,
      hidden_reason = case when s.status = 'hidden' then s.hidden_reason else p.hidden_reason end
  from jsonb_to_recordset(seed) as s(
    city text, ce1_seq integer, location_lat double precision, location_lng double precision,
    outside_coverage boolean, status text, hidden_reason text
  )
  join public.city_puzzle_questions q on q.city = s.city and q.seq = s.ce1_seq
  where p.legacy_price_id = q.id and p.city = s.city and p.type = 'price';
  get diagnostics legacy_matches = row_count;
  if legacy_matches <> 80 then
    raise exception 'HL-Q1 expected 80 existing CE1 question pool rows, matched %', legacy_matches;
  end if;

  with rows as (
    select *
    from jsonb_to_recordset(seed) as s(
      id uuid, city text, type text, place_zh text, place_en text, location_lat double precision,
      location_lng double precision, prompt_zh text, prompt_en text, kind text, choices jsonb,
      currency text, rate numeric, source_url text, checked_on date, status text,
      outside_coverage boolean, hidden_reason text, answer jsonb, typed_aliases text[],
      usd numeric, local_amount numeric
    )
    where s.id is not null
  ), inserted as (
    insert into private.question_pool (
      id, city, type, place_zh, place_en, location_lat, location_lng, prompt_zh, prompt_en,
      kind, choices, currency, rate, source_url, checked_on, status, outside_coverage, hidden_reason
    )
    select id, city, type, place_zh, place_en, location_lat, location_lng, prompt_zh, prompt_en,
      kind, choices, currency, rate, source_url, checked_on,
      case when status = 'hidden' then 'hidden' else 'published' end,
      outside_coverage, hidden_reason
    from rows
    on conflict (id) do nothing
    returning id
  )
  insert into private.question_pool_secrets (id, answer, typed_aliases, usd, local_amount)
  select r.id, r.answer, r.typed_aliases, r.usd, r.local_amount
  from rows r
  join inserted i on i.id = r.id;
end;
$migration$;
